import json

with open('ios_crash.ips') as f:
    lines = f.readlines()
    # Skip first line (header JSON), parse the body JSON
    body = json.loads(''.join(lines[1:]))

# Find frames without 'symbol' field across all threads
unsymbolicated = []
for tidx, thread in enumerate(body['threads']):
    for fidx, frame in enumerate(thread.get('frames', [])):
        if 'symbol' not in frame:
            unsymbolicated.append((tidx, fidx, frame))

print(f'Total unsymbolicated frames: {len(unsymbolicated)}')
for tidx, fidx, frame in unsymbolicated[:30]:
    print(f'  Thread {tidx}, Frame {fidx}: imageIndex={frame.get(\"imageIndex\")}, imageOffset={frame.get(\"imageOffset\")}')

# Also check lastExceptionBacktrace
print()
